import numpy as np

def rank_nullity(A):
    A = np.array(A, dtype=float)
    r = int(np.linalg.matrix_rank(A))
    return (r, A.shape[1] - r)

def kernel_basis(A):
    A = np.array(A, dtype=float)
    r = int(np.linalg.matrix_rank(A))
    _, _, Vt = np.linalg.svd(A)
    return Vt[r:].T
